// Generated by vibelang from src/state/threadUndo.ts; the migrate flow writes it again with each batch.
// Shared across hook instances so sidebar, header and menu actions invalidate each other.
const currentActions = new Map();
const listeners = new Set();
export function subscribe(listener) {
    listeners.add(listener);
    return () => {
        listeners.delete(listener);
    };
}
function notify() {
    for (const listener of listeners)
        listener();
}
export function begin(kind, threadKey) {
    const key = JSON.stringify([kind, threadKey]);
    const token = Symbol();
    currentActions.set(key, token);
    notify();
    const isCurrent = () => currentActions.get(key) === token;
    return {
        isCurrent,
        finish: () => {
            if (isCurrent()) {
                currentActions.delete(key);
                notify();
            }
        },
    };
}
export function invalidate(kind, threadKey) {
    currentActions.delete(JSON.stringify([kind, threadKey]));
    notify();
}
export function planThreadUndo(action, thread) {
    if (action === "snooze")
        return [{ action: "unsnooze" }];
    const pin = {
        action: "pin",
        ...(thread?.pinOrderKey != null ? { orderKey: thread.pinOrderKey } : {}),
    };
    // Pinning clears snooze on the server; restore it after restoring pin placement.
    const snooze = thread?.snoozedUntil != null
        ? [{ action: "snooze", snoozedUntil: thread.snoozedUntil }]
        : [];
    if (action === "unpin")
        return [pin, ...snooze];
    return [{ action: "unsettle" }, ...(thread?.pinnedAt != null ? [pin] : []), ...snooze];
}
export async function executeThreadUndo(plan, execute, succeeded) {
    let result = await execute(plan[0]);
    for (const step of plan.slice(1)) {
        if (!succeeded(result))
            return result;
        // A snooze can expire before Undo runs, and the server rejects an expired restore.
        // @effect-diagnostics-next-line globalDate:off
        if (step.action === "snooze" && Date.parse(step.snoozedUntil) <= Date.now())
            continue;
        result = await execute(step);
    }
    return result;
}
